// site/src/english/data/reading/a2-engineering.ts
// A2 engineering-stream reading texts. Bilingual; inline-glossed; targetWords -> vocabA2 ids.
import type { ReadingUnit } from "~/english/types";

export const a2Engineering: ReadingUnit[] = [
  {"id":"code-review-101","level":"A2","stream":"engineering","title":{"en":"Reading a code review","ru":"Читаем код-ревью"},"blurb":{"en":"The first English you meet on a real team: a reviewer's comments on your pull request. Learn to read them without panic.","ru":"Первый английский на реальной команде: комментарии ревьюера к твоему pull request. Учимся читать их без паники."},"source":{"en":"Pull request review thread","ru":"Тред ревью pull request"},"passages":[{"en":"Thanks for the PR! Overall this looks solid, but I left a few comments. Nothing blocking — mostly nits and one thing we should discuss before merging.","ru":"Спасибо за PR! В целом выглядит крепко, но я оставил пару комментариев. Ничего блокирующего — в основном мелочи и одна вещь, которую стоит обсудить перед мержем.","words":[{"id":"solid","w":"solid","ru":"надёжный, крепкий","gloss":"good and reliable; not weak","pos":"adj","example":"The design looks solid."},{"id":"blocking","w":"blocking","ru":"блокирующий (мешает мержу)","gloss":"serious enough to stop the merge","pos":"adj","example":"This bug is blocking the release."},{"id":"nit","w":"nit","ru":"мелкая придирка","gloss":"a tiny, low-importance comment","pos":"noun","ipa":"nɪt","example":"Just a nit: rename this variable."},{"id":"merge","w":"merge","ru":"слить ветки (мерж)","gloss":"to join your branch into the main code","pos":"verb","example":"Let's merge after CI passes."}]},{"en":"This function is doing too much. Can you split it up? It would be easier to test and reason about if each part had a single responsibility.","ru":"Эта функция делает слишком много. Можешь разбить её? Будет легче тестировать и понимать, если у каждой части будет одна ответственность.","words":[{"id":"split-up","w":"split up","ru":"разбить на части","gloss":"to break one thing into smaller parts","pos":"phrase","example":"Split up this big file."},{"id":"reason-about","w":"reason about","ru":"осмыслить, понять логику","gloss":"to think clearly about how it works","pos":"phrase","example":"Hard to reason about this loop."},{"id":"responsibility","w":"responsibility","ru":"ответственность, задача","gloss":"the one job a piece of code should do","pos":"noun","ipa":"rɪˌspɒnsɪˈbɪlɪti"}]},{"en":"Heads up: this query is not using an index, so it will do a full table scan. On production data that could be slow. Let's add an index or rewrite it.","ru":"Имей в виду: этот запрос не использует индекс, поэтому сделает полное сканирование таблицы. На боевых данных это может быть медленно. Давай добавим индекс или перепишем его.","words":[{"id":"heads-up","w":"heads up","ru":"предупреждение, имей в виду","gloss":"a friendly warning about something","pos":"phrase","example":"Heads up: the API changed."},{"id":"full-table-scan","w":"full table scan","ru":"полное сканирование таблицы","gloss":"the database reads every row, which is slow","pos":"phrase"},{"id":"production","w":"production","ru":"продакшн, боевая среда","gloss":"the live system real users use","pos":"noun","ipa":"prəˈdʌkʃən"}]},{"en":"Nit: typo in the comment — `recieve` should be `receive`. Feel free to ignore if you're in a hurry, but it'd be nice to fix while we're here.","ru":"Мелочь: опечатка в комментарии — `recieve` должно быть `receive`. Можешь проигнорировать, если торопишься, но было бы хорошо поправить, раз уж мы здесь.","words":[{"id":"typo","w":"typo","ru":"опечатка","gloss":"a small spelling mistake","pos":"noun","ipa":"ˈtaɪpəʊ"},{"id":"feel-free","w":"feel free to","ru":"не стесняйся / можешь смело","gloss":"you are allowed to; no pressure","pos":"phrase","example":"Feel free to push back."},{"id":"in-a-hurry","w":"in a hurry","ru":"в спешке, торопишься","gloss":"needing to do something fast","pos":"phrase"}]},{"en":"I'm going to request changes for now, but it's close. Address the comments above and ping me — I'll re-review and approve quickly.","ru":"Пока поставлю «запрос изменений», но мы близко. Поправь комментарии выше и пингани меня — я быстро пересмотрю и заапрувлю.","words":[{"id":"request-changes","w":"request changes","ru":"запросить изменения (статус ревью)","gloss":"a review status that asks for edits before merge","pos":"phrase"},{"id":"address","w":"address","ru":"обработать, разобраться (с комментарием)","gloss":"to deal with or fix something raised","pos":"verb","example":"Please address the failing test."},{"id":"ping","w":"ping","ru":"пингануть, написать/позвать","gloss":"to send someone a quick message","pos":"verb","example":"Ping me when it's ready."},{"id":"approve","w":"approve","ru":"одобрить, заапрувить","gloss":"to accept the PR so it can merge","pos":"verb","ipa":"əˈpruːv"}]}],"phrases":[{"id":"ph-lgtm","en":"LGTM","ru":"«мне ок» (Looks Good To Me)","note":{"en":"Said when you approve with no concerns.","ru":"Говорят, когда одобряешь без замечаний."}},{"id":"ph-wip","en":"WIP","ru":"в работе (Work In Progress)","note":{"en":"Marks an unfinished PR not ready for review.","ru":"Помечает незаконченный PR, ещё не готовый к ревью."}},{"id":"ph-ptal","en":"PTAL","ru":"глянь, пожалуйста (Please Take Another Look)","note":{"en":"Asks the reviewer to look again after edits.","ru":"Просит ревьюера посмотреть снова после правок."}},{"id":"ph-push-back","en":"push back","ru":"возразить, не согласиться","note":{"en":"To disagree with feedback — politely. It's normal.","ru":"Не согласиться с фидбеком — вежливо. Это нормально."}},{"id":"ph-out-of-scope","en":"out of scope","ru":"вне рамок задачи","note":{"en":"Not part of this PR's goal — do it later.","ru":"Не входит в цель этого PR — сделать позже."}},{"id":"ph-good-catch","en":"good catch","ru":"хорошо подметил","note":{"en":"Praise when someone spots a real problem.","ru":"Похвала, когда кто-то заметил настоящую проблему."}}],"questions":[{"id":"q-blocking","q":{"en":"The reviewer says the comments are “nothing blocking”. What does that mean for you?","ru":"Ревьюер пишет, что комментарии «nothing blocking». Что это значит для тебя?"},"options":[{"en":"You must stop and cannot merge at all.","ru":"Надо остановиться, мержить нельзя совсем."},{"en":"Nothing here forces you to stop — fix them, then merge.","ru":"Ничто не заставляет остановиться — поправь и мержи."},{"en":"The reviewer rejected the whole PR.","ru":"Ревьюер отклонил весь PR."}],"answer":1,"explain":{"en":"\"Blocking\" means serious enough to stop the merge. \"Nothing blocking\" = no hard stoppers.","ru":"«Blocking» = достаточно серьёзно, чтобы остановить мерж. «Nothing blocking» = жёстких стопперов нет."}},{"id":"q-index","q":{"en":"Why is the reviewer worried about the query?","ru":"Почему ревьюер беспокоится из-за запроса?"},"options":[{"en":"It has a typo in a comment.","ru":"В комментарии опечатка."},{"en":"It does a full table scan, which can be slow on production.","ru":"Делает полное сканирование таблицы — на проде может быть медленно."},{"en":"It does too many things at once.","ru":"Делает слишком много за раз."}],"answer":1,"explain":{"en":"No index → the database reads every row (full table scan) → slow on real data.","ru":"Нет индекса → БД читает каждую строку (full table scan) → медленно на реальных данных."}},{"id":"q-next","q":{"en":"The review status is \"request changes\". What should you do next?","ru":"Статус ревью — «request changes». Что делать дальше?"},"options":[{"en":"Nothing — it will merge by itself.","ru":"Ничего — смержится само."},{"en":"Open a brand-new PR from scratch.","ru":"Открыть новый PR с нуля."},{"en":"Address the comments, then ping the reviewer to look again.","ru":"Обработать комментарии и пингануть ревьюера, чтобы глянул снова."}],"answer":2,"explain":{"en":"\"Request changes\" asks for edits before merge. Fix, then ask for re-review (PTAL).","ru":"«Request changes» просит правки до мержа. Поправь и попроси пересмотреть (PTAL)."}}],"targetWords":["ngsl:0730","ngsl:0332","ngsl:0702","ngsl:0713","ngsl:0558","ngsl:0414"]},
  {"id":"a2e-standup-update","level":"A2","stream":"engineering","title":{"en":"A standup update","ru":"Сообщение на стендапе"},"blurb":{"en":"Every morning your team has a short meeting. Each person says what they did, what they plan to do, and if anything is blocking them. Learn the simple English for this.","ru":"Каждое утро команда проводит короткую встречу. Каждый говорит, что сделал, что планирует и есть ли что-то, что мешает работать. Учим простой английский для этого."},"source":{"en":"Daily standup message","ru":"Сообщение на ежедневном стендапе"},"passages":[{"en":"Yesterday I finished the login form. I fixed a bug where the button did not work on mobile.","ru":"Вчера я закончил форму входа. Я исправил баг, из-за которого кнопка не работала на мобильном.","words":[{"id":"a2e-standup-update-w1","w":"standup","ru":"стендап (ежедневная короткая встреча)","gloss":"a short daily team meeting, usually 15 minutes","pos":"noun","ipa":"ˈstændʌp","example":"We have a standup every morning at 10."},{"id":"a2e-standup-update-w2","w":"bug","ru":"баг, ошибка в коде","gloss":"a mistake in the code that causes wrong behaviour","pos":"noun","ipa":"bʌɡ","example":"I found a bug in the payment form."}]},{"en":"Today I will start work on the user profile page. I need to add a photo upload.","ru":"Сегодня я начну работу над страницей профиля пользователя. Мне нужно добавить загрузку фото.","words":[{"id":"a2e-standup-update-w3","w":"upload","ru":"загрузка (файла на сервер)","gloss":"to send a file from your computer to a server","pos":"verb","ipa":"ˈʌpləʊd","example":"Users can upload a profile photo."}]},{"en":"No blockers. I am ready to review someone's pull request if needed.","ru":"Блокеров нет. Я готов проревьюить чей-нибудь пул-реквест, если нужно.","words":[{"id":"a2e-standup-update-w4","w":"blocker","ru":"блокер (проблема, мешающая двигаться вперёд)","gloss":"a problem that stops you from continuing your work","pos":"noun","ipa":"ˈblɒkə","example":"I have no blockers today."},{"id":"a2e-standup-update-w5","w":"pull request","ru":"пул-реквест (запрос на добавление кода)","gloss":"a request to add your code changes to the main codebase","pos":"phrase","example":"Can you review my pull request?"}]}],"phrases":[{"id":"a2e-standup-update-p1","en":"Yesterday I finished…","ru":"Вчера я закончил…","note":{"en":"Use this to say what you completed the day before.","ru":"Используй это, чтобы рассказать, что ты завершил накануне."}},{"id":"a2e-standup-update-p2","en":"Today I will…","ru":"Сегодня я буду…","note":{"en":"Use this to describe your plan for the current day.","ru":"Используй это, чтобы описать план на текущий день."}},{"id":"a2e-standup-update-p3","en":"No blockers.","ru":"Блокеров нет.","note":{"en":"Say this when nothing is stopping your work. It is the most common standup phrase.","ru":"Говори это, когда ничто не мешает работе. Это самая частая фраза на стендапе."}},{"id":"a2e-standup-update-p4","en":"I am blocked by…","ru":"Меня блокирует…","note":{"en":"Use this when something is stopping your work, for example: 'I am blocked by a failing test.'","ru":"Используй это, когда что-то мешает работе, например: «Меня блокирует упавший тест»."}}],"questions":[{"id":"a2e-standup-update-q1","q":{"en":"What did the developer finish yesterday?","ru":"Что разработчик завершил вчера?"},"options":[{"en":"The login form","ru":"Форму входа"},{"en":"The user profile page","ru":"Страницу профиля пользователя"},{"en":"The photo upload feature","ru":"Функцию загрузки фото"}],"answer":0,"explain":{"en":"The text says 'Yesterday I finished the login form.'","ru":"В тексте сказано: «Вчера я закончил форму входа»."}},{"id":"a2e-standup-update-q2","q":{"en":"What will the developer do today?","ru":"Что разработчик будет делать сегодня?"},"options":[{"en":"Fix a mobile bug","ru":"Исправить баг на мобильном"},{"en":"Start the user profile page","ru":"Начать работу над страницей профиля"},{"en":"Attend a standup meeting","ru":"Присутствовать на стендапе"}],"answer":1,"explain":{"en":"The text says 'Today I will start work on the user profile page.'","ru":"В тексте сказано: «Сегодня я начну работу над страницей профиля пользователя»."}},{"id":"a2e-standup-update-q3","q":{"en":"Does the developer have any blockers?","ru":"Есть ли у разработчика блокеры?"},"options":[{"en":"Yes, the button does not work.","ru":"Да, кнопка не работает."},{"en":"Yes, the photo upload is broken.","ru":"Да, загрузка фото сломана."},{"en":"No, there are no blockers.","ru":"Нет, блокеров нет."}],"answer":2,"explain":{"en":"The text says 'No blockers.'","ru":"В тексте сказано: «Блокеров нет»."}},{"id":"a2e-standup-update-q4","q":{"en":"What does the developer offer to do for the team?","ru":"Что разработчик предлагает сделать для команды?"},"options":[{"en":"Write new tests","ru":"Написать новые тесты"},{"en":"Review someone's pull request","ru":"Проревьюить чей-нибудь пул-реквест"},{"en":"Deploy the app","ru":"Задеплоить приложение"}],"answer":1,"explain":{"en":"The text says 'I am ready to review someone's pull request if needed.'","ru":"В тексте сказано: «Я готов проревьюить чей-нибудь пул-реквест, если нужно»."}}],"targetWords":["ngsl:0609","ngsl:0136","ngsl:0414","ngsl:0580","ngsl:0067"]},
  {"id":"a2e-error-explained","level":"A2","stream":"engineering","title":{"en":"An error message explained","ru":"Объяснение сообщения об ошибке"},"blurb":{"en":"You see a scary error in the terminal. Your teammate explains it in plain English. Learn to read both the error and the explanation.","ru":"Ты видишь страшную ошибку в терминале. Коллега объясняет её простым английским. Учимся читать и ошибку, и объяснение."},"source":{"en":"Terminal error + team chat message","ru":"Ошибка в терминале + сообщение в командном чате"},"passages":[{"en":"You see this error in the terminal: 'Error: Cannot connect to database. Connection refused. Port 5432.'","ru":"Ты видишь эту ошибку в терминале: «Error: Cannot connect to database. Connection refused. Port 5432.»","words":[{"id":"a2e-error-explained-w1","w":"terminal","ru":"терминал (консоль, командная строка)","gloss":"the black text window where you run commands","pos":"noun","ipa":"ˈtɜːmɪnəl","example":"Open the terminal and run the command."},{"id":"a2e-error-explained-w2","w":"database","ru":"база данных","gloss":"a place where an app stores its data","pos":"noun","ipa":"ˈdeɪtəbeɪs","example":"The app reads user data from the database."},{"id":"a2e-error-explained-w3","w":"connection refused","ru":"соединение отклонено (сервер не отвечает)","gloss":"the server is not running or not listening on that port","pos":"phrase","example":"Connection refused means the server is off."},{"id":"a2e-error-explained-w4","w":"port","ru":"порт (номер канала связи)","gloss":"a number that identifies a specific service on a server","pos":"noun","ipa":"pɔːt","example":"PostgreSQL uses port 5432 by default."}]},{"en":"Your teammate writes in chat: 'Hey, don't worry. This error means the database is not running. You need to start it first. Run this command: docker compose up db.'","ru":"Коллега пишет в чате: «Эй, не переживай. Эта ошибка означает, что база данных не запущена. Тебе нужно сначала её запустить. Выполни эту команду: docker compose up db».","words":[{"id":"a2e-error-explained-w5","w":"don't worry","ru":"не переживай, не волнуйся","gloss":"a friendly way to say the problem is not serious","pos":"phrase","example":"Don't worry, I can help you fix it."},{"id":"a2e-error-explained-w6","w":"command","ru":"команда (инструкция для терминала)","gloss":"text you type in the terminal to tell the computer what to do","pos":"noun","ipa":"kəˈmɑːnd","example":"Run the command to start the server."}]},{"en":"You run the command. The database starts. The error is gone. You can continue your work.","ru":"Ты выполняешь команду. База данных запускается. Ошибка исчезает. Ты можешь продолжать работу.","words":[{"id":"a2e-error-explained-w7","w":"is gone","ru":"исчезла, пропала","gloss":"no longer there; disappeared","pos":"phrase","example":"After the fix, the error is gone."}]}],"phrases":[{"id":"a2e-error-explained-p1","en":"Don't worry.","ru":"Не переживай.","note":{"en":"A friendly opener that tells the reader the problem is fixable.","ru":"Дружеское начало, которое говорит читателю, что проблема решаема."}},{"id":"a2e-error-explained-p2","en":"This error means…","ru":"Эта ошибка означает…","note":{"en":"Use this to explain what an error message is telling the developer.","ru":"Используй это, чтобы объяснить, что сообщение об ошибке говорит разработчику."}},{"id":"a2e-error-explained-p3","en":"You need to… first.","ru":"Тебе нужно сначала…","note":{"en":"Use this to give a step-by-step instruction with a required first action.","ru":"Используй это, чтобы дать пошаговую инструкцию с обязательным первым шагом."}},{"id":"a2e-error-explained-p4","en":"Run this command:","ru":"Выполни эту команду:","note":{"en":"The standard way to give a terminal command to a colleague.","ru":"Стандартный способ передать коллеге команду для терминала."}}],"questions":[{"id":"a2e-error-explained-q1","q":{"en":"What does the error message say?","ru":"Что говорит сообщение об ошибке?"},"options":[{"en":"The file is not found.","ru":"Файл не найден."},{"en":"The database cannot be reached.","ru":"К базе данных нельзя подключиться."},{"en":"The port number is wrong.","ru":"Номер порта неверный."}],"answer":1,"explain":{"en":"'Cannot connect to database. Connection refused.' means the database cannot be reached.","ru":"«Cannot connect to database. Connection refused.» означает, что к базе данных нельзя подключиться."}},{"id":"a2e-error-explained-q2","q":{"en":"According to the teammate, what is the real problem?","ru":"По словам коллеги, в чём настоящая проблема?"},"options":[{"en":"The port number is incorrect.","ru":"Номер порта неверный."},{"en":"The database is not running.","ru":"База данных не запущена."},{"en":"The command has a typo.","ru":"В команде есть опечатка."}],"answer":1,"explain":{"en":"The teammate says 'this error means the database is not running.'","ru":"Коллега говорит: «Эта ошибка означает, что база данных не запущена»."}},{"id":"a2e-error-explained-q3","q":{"en":"What does the developer do to fix the problem?","ru":"Что разработчик делает, чтобы исправить проблему?"},"options":[{"en":"Restarts the computer.","ru":"Перезапускает компьютер."},{"en":"Asks the teammate for more help.","ru":"Просит коллегу о дополнительной помощи."},{"en":"Runs the command to start the database.","ru":"Выполняет команду для запуска базы данных."}],"answer":2,"explain":{"en":"The text says 'You run the command. The database starts.'","ru":"В тексте сказано: «Ты выполняешь команду. База данных запускается»."}},{"id":"a2e-error-explained-q4","q":{"en":"What happens after the developer runs the command?","ru":"Что происходит после того, как разработчик выполняет команду?"},"options":[{"en":"A new error appears.","ru":"Появляется новая ошибка."},{"en":"The error is gone and work continues.","ru":"Ошибка исчезает и работа продолжается."},{"en":"The teammate checks the code.","ru":"Коллега проверяет код."}],"answer":1,"explain":{"en":"The text says 'The error is gone. You can continue your work.'","ru":"В тексте сказано: «Ошибка исчезает. Ты можешь продолжать работу»."}}],"targetWords":["ngsl:0136","ngsl:0192","ngsl:0711","ngsl:0133","ngsl:0580"]},
  {"id":"a2e-deploy-message","level":"A2","stream":"engineering","title":{"en":"A deploy message in chat","ru":"Сообщение о деплое в чате"},"blurb":{"en":"When a developer sends new code to the production server, they write a short message in the team chat. Learn to read these deploy announcements.","ru":"Когда разработчик отправляет новый код на продакшн-сервер, он пишет короткое сообщение в командном чате. Учимся читать такие объявления о деплое."},"source":{"en":"Team chat deploy announcement","ru":"Объявление о деплое в командном чате"},"passages":[{"en":"Deploying version 2.4.1 to production. This release includes a fix for the login bug and a small update to the user profile page.","ru":"Деплоим версию 2.4.1 на продакшн. Этот релиз включает исправление бага при входе и небольшое обновление страницы профиля пользователя.","words":[{"id":"a2e-deploy-message-w1","w":"deploying","ru":"деплоим, выкатываем (отправляем код на сервер)","gloss":"sending the new code to the live server so users can see it","pos":"verb","ipa":"dɪˈplɔɪɪŋ","example":"We are deploying the new feature tonight."},{"id":"a2e-deploy-message-w2","w":"production","ru":"продакшн (живой сервер, который видят пользователи)","gloss":"the real live system that real users use","pos":"noun","ipa":"prəˈdʌkʃən","example":"Never test on production."},{"id":"a2e-deploy-message-w3","w":"release","ru":"релиз (выпуск новой версии)","gloss":"a new version of the software that is sent to users","pos":"noun","ipa":"rɪˈliːs","example":"The release includes three new features."},{"id":"a2e-deploy-message-w4","w":"includes","ru":"включает (содержит в себе)","gloss":"contains as a part","pos":"verb","ipa":"ɪnˈkluːdz","example":"This update includes a security fix."}]},{"en":"The deploy is complete. All services are running. No errors in the logs.","ru":"Деплой завершён. Все сервисы работают. В логах нет ошибок.","words":[{"id":"a2e-deploy-message-w5","w":"complete","ru":"завершён, выполнен","gloss":"finished; done","pos":"adj","ipa":"kəmˈpliːt","example":"The build is complete."},{"id":"a2e-deploy-message-w6","w":"logs","ru":"логи (записи о работе программы)","gloss":"a file where the server writes messages about what it is doing","pos":"noun","ipa":"lɒɡz","example":"Check the logs to find the error."}]},{"en":"If you see any problems, please send a message in this channel. We will roll back if needed.","ru":"Если вы заметите какие-либо проблемы, пожалуйста, напишите сообщение в этом канале. При необходимости мы сделаем откат.","words":[{"id":"a2e-deploy-message-w7","w":"channel","ru":"канал (чат-комната в Slack или другом мессенджере)","gloss":"a chat room in a messaging app like Slack","pos":"noun","ipa":"ˈtʃænəl","example":"Post updates in the #deployments channel."},{"id":"a2e-deploy-message-w8","w":"roll back","ru":"откатить (вернуться к предыдущей версии)","gloss":"to go back to the previous working version of the software","pos":"phrase","ipa":"rəʊl bæk","example":"If the deploy breaks something, we roll back."}]}],"phrases":[{"id":"a2e-deploy-message-p1","en":"Deploying version X.Y.Z to production.","ru":"Деплоим версию X.Y.Z на продакшн.","note":{"en":"The standard opening line for a deploy announcement.","ru":"Стандартная первая строка объявления о деплое."}},{"id":"a2e-deploy-message-p2","en":"The deploy is complete.","ru":"Деплой завершён.","note":{"en":"Written after the deploy finishes successfully, to inform the team.","ru":"Пишется после успешного завершения деплоя, чтобы сообщить команде."}},{"id":"a2e-deploy-message-p3","en":"No errors in the logs.","ru":"В логах нет ошибок.","note":{"en":"A short health check confirmation after a deploy.","ru":"Краткое подтверждение проверки после деплоя."}},{"id":"a2e-deploy-message-p4","en":"We will roll back if needed.","ru":"При необходимости мы сделаем откат.","note":{"en":"Reassures the team that there is a safe way to undo the deploy.","ru":"Заверяет команду, что деплой можно безопасно отменить."}}],"questions":[{"id":"a2e-deploy-message-q1","q":{"en":"What version is being deployed?","ru":"Какая версия деплоится?"},"options":[{"en":"2.1.4","ru":"2.1.4"},{"en":"2.4.1","ru":"2.4.1"},{"en":"4.2.1","ru":"4.2.1"}],"answer":1,"explain":{"en":"The text says 'Deploying version 2.4.1 to production.'","ru":"В тексте сказано: «Деплоим версию 2.4.1 на продакшн»."}},{"id":"a2e-deploy-message-q2","q":{"en":"What does this release fix?","ru":"Что исправляет этот релиз?"},"options":[{"en":"A bug in the payment service","ru":"Баг в платёжном сервисе"},{"en":"A bug in the login","ru":"Баг при входе"},{"en":"A bug in the deploy script","ru":"Баг в скрипте деплоя"}],"answer":1,"explain":{"en":"The text says 'a fix for the login bug'.","ru":"В тексте сказано: «исправление бага при входе»."}},{"id":"a2e-deploy-message-q3","q":{"en":"What does the developer check after the deploy?","ru":"Что разработчик проверяет после деплоя?"},"options":[{"en":"The user count","ru":"Количество пользователей"},{"en":"The logs","ru":"Логи"},{"en":"The pull requests","ru":"Пул-реквесты"}],"answer":1,"explain":{"en":"The text says 'No errors in the logs', which means the logs were checked.","ru":"В тексте сказано: «В логах нет ошибок», что означает, что логи были проверены."}},{"id":"a2e-deploy-message-q4","q":{"en":"What will the team do if there are problems?","ru":"Что команда сделает, если возникнут проблемы?"},"options":[{"en":"Deploy a new version immediately.","ru":"Немедленно задеплоит новую версию."},{"en":"Roll back to the previous version.","ru":"Откатится к предыдущей версии."},{"en":"Restart all the services.","ru":"Перезапустит все сервисы."}],"answer":1,"explain":{"en":"The text says 'We will roll back if needed.'","ru":"В тексте сказано: «При необходимости мы сделаем откат»."}}],"targetWords":["ngsl:0786","ngsl:0581","ngsl:0223","ngsl:0323","ngsl:0347"]},
  {"id":"a2e-git-basics","level":"A2","stream":"engineering","title":{"en":"Basic Git Workflow","ru":"Базовый рабочий процесс в Git"},"blurb":{"en":"A short note a senior engineer left for a newcomer: how to save your work and share it with the team using git.","ru":"Короткая заметка, которую опытный инженер оставил новичку: как сохранить работу и поделиться ею с командой через git."},"source":{"en":"Internal onboarding note","ru":"Внутренняя заметка для новых сотрудников"},"passages":[{"en":"Hi! Here is a quick note about how we use git on this team. Git is a tool that saves every change you make to the code. It also lets the whole team work together without losing anyone's work.","ru":"Привет! Вот короткая заметка о том, как мы используем git в нашей команде. Git — это инструмент, который сохраняет каждое изменение в коде. Он также позволяет всей команде работать вместе, не теряя ничью работу.","words":[{"id":"a2e-git-basics-w1","w":"change","ru":"изменение","gloss":"something you add, remove, or edit in the code","pos":"noun","ipa":"/tʃeɪndʒ/","example":"I made a small change to the login page."},{"id":"a2e-git-basics-w2","w":"tool","ru":"инструмент","gloss":"a program that helps you do a specific job","pos":"noun","ipa":"/tuːl/","example":"Git is a very popular tool for teams."}]},{"en":"When you finish a piece of work, you save it with a commit. A commit is like a snapshot. It records what changed and adds a short message to explain why. For example: 'fix login button'. Always write a clear message — your teammates will read it.","ru":"Когда ты заканчиваешь часть работы, ты сохраняешь её с помощью коммита. Коммит — это как снимок. Он записывает, что изменилось, и содержит короткое сообщение с объяснением причины. Например: 'fix login button'. Всегда пиши понятное сообщение — твои коллеги будут его читать.","words":[{"id":"a2e-git-basics-w3","w":"commit","ru":"коммит (сохранение изменений в git)","gloss":"a saved snapshot of your code changes with a short message","pos":"noun","ipa":"/kəˈmɪt/","example":"I made three commits today."},{"id":"a2e-git-basics-w4","w":"message","ru":"сообщение","gloss":"a short text that explains what the commit does","pos":"noun","ipa":"/ˈmɛsɪdʒ/","example":"Write a clear commit message."},{"id":"a2e-git-basics-w5","w":"snapshot","ru":"снимок (состояние кода в момент времени)","gloss":"a saved copy of something at one point in time","pos":"noun","ipa":"/ˈsnæpʃɒt/","example":"Each commit is a snapshot of the project."}]},{"en":"After you commit, you push your work. Push sends your commits from your computer to the remote server. The remote server is where the team's code lives online. Use the command: git push.","ru":"После коммита ты делаешь push. Push отправляет твои коммиты с твоего компьютера на удалённый сервер. Удалённый сервер — это место, где код команды хранится онлайн. Используй команду: git push.","words":[{"id":"a2e-git-basics-w6","w":"push","ru":"пуш — отправить коммиты на сервер","gloss":"to send your local commits to the remote server","pos":"verb","ipa":"/pʊʃ/","example":"Don't forget to push before you leave."},{"id":"a2e-git-basics-w7","w":"remote","ru":"удалённый (сервер / репозиторий)","gloss":"the copy of the code stored online, not on your computer","pos":"adj","ipa":"/rɪˈməʊt/","example":"Push your branch to the remote."}]},{"en":"When your teammates push new code, you need to get those updates. Use git pull. This downloads the latest commits and adds them to your local copy. Do this every morning before you start work.","ru":"Когда твои коллеги пушат новый код, тебе нужно получить эти обновления. Используй git pull. Это скачивает последние коммиты и добавляет их в твою локальную копию. Делай это каждое утро перед началом работы.","words":[{"id":"a2e-git-basics-w8","w":"pull","ru":"пул — скачать последние изменения с сервера","gloss":"to download the latest commits from the remote to your computer","pos":"verb","ipa":"/pʊl/","example":"Pull first, then start coding."},{"id":"a2e-git-basics-w9","w":"local","ru":"локальный (на твоём компьютере)","gloss":"existing on your own computer, not the server","pos":"adj","ipa":"/ˈləʊkəl/","example":"Your local copy may be behind the remote."}]},{"en":"So the basic loop is: write code → commit → push. And when you start a new day: pull → write code → commit → push. That's it! Ask me if you have questions.","ru":"Итак, основной цикл такой: пишешь код → коммит → пуш. А когда начинаешь новый день: пул → пишешь код → коммит → пуш. Вот и всё! Спрашивай, если есть вопросы.","words":[{"id":"a2e-git-basics-w10","w":"loop","ru":"цикл (повторяющийся процесс)","gloss":"a set of steps you repeat again and again","pos":"noun","ipa":"/luːp/","example":"The build loop runs every hour."}]}],"phrases":[{"id":"a2e-git-basics-p1","en":"git commit -m \"…\"","ru":"git commit -m \"…\" — сохранить изменения с сообщением","note":{"en":"The -m flag lets you write the commit message directly in the command.","ru":"Флаг -m позволяет написать сообщение коммита прямо в команде."}},{"id":"a2e-git-basics-p2","en":"git push","ru":"git push — отправить коммиты на сервер","note":{"en":"Sends your commits to the remote so teammates can see them.","ru":"Отправляет твои коммиты на удалённый сервер, чтобы коллеги их увидели."}},{"id":"a2e-git-basics-p3","en":"git pull","ru":"git pull — получить последние изменения с сервера","note":{"en":"Downloads and applies the latest commits from the remote server.","ru":"Скачивает и применяет последние коммиты с удалённого сервера."}},{"id":"a2e-git-basics-p4","en":"behind the remote","ru":"отстаёт от удалённого репозитория","note":{"en":"Your local copy is missing commits that are already on the server.","ru":"В твоей локальной копии нет коммитов, которые уже есть на сервере."}}],"questions":[{"id":"a2e-git-basics-q1","q":{"en":"What is a commit in git?","ru":"Что такое коммит в git?"},"options":[{"en":"A command that deletes your code.","ru":"Команда, которая удаляет твой код."},{"en":"A saved snapshot of your changes with a short message.","ru":"Сохранённый снимок твоих изменений с коротким сообщением."},{"en":"A way to download code from the server.","ru":"Способ скачать код с сервера."}],"answer":1,"explain":{"en":"The note says: 'A commit is like a snapshot. It records what changed and adds a short message.'","ru":"В заметке написано: «Коммит — это как снимок. Он записывает, что изменилось, и содержит короткое сообщение»."}},{"id":"a2e-git-basics-q2","q":{"en":"What does 'git push' do?","ru":"Что делает команда «git push»?"},"options":[{"en":"It saves a snapshot of your code locally.","ru":"Сохраняет снимок твоего кода локально."},{"en":"It downloads the latest changes from the server.","ru":"Скачивает последние изменения с сервера."},{"en":"It sends your commits to the remote server.","ru":"Отправляет твои коммиты на удалённый сервер."}],"answer":2,"explain":{"en":"'Push sends your commits from your computer to the remote server.'","ru":"«Push отправляет твои коммиты с твоего компьютера на удалённый сервер»."}},{"id":"a2e-git-basics-q3","q":{"en":"When should you run 'git pull'?","ru":"Когда нужно запускать «git pull»?"},"options":[{"en":"Only on Fridays before the weekend.","ru":"Только по пятницам перед выходными."},{"en":"Every morning before you start work.","ru":"Каждое утро перед началом работы."},{"en":"After you push your commits.","ru":"После того как ты сделал push своих коммитов."}],"answer":1,"explain":{"en":"The note says: 'Do this every morning before you start work.'","ru":"В заметке написано: «Делай это каждое утро перед началом работы»."}},{"id":"a2e-git-basics-q4","q":{"en":"What is the correct order of the basic daily loop?","ru":"Какой правильный порядок основного ежедневного цикла?"},"options":[{"en":"push → commit → write code","ru":"push → commit → пишем код"},{"en":"pull → write code → commit → push","ru":"pull → пишем код → commit → push"},{"en":"commit → pull → write code → push","ru":"commit → pull → пишем код → push"}],"answer":1,"explain":{"en":"The note says the daily loop starts with pull, then write code, commit, and push.","ru":"В заметке сказано, что ежедневный цикл начинается с pull, затем пишешь код, коммит и push."}}],"targetWords":["ngsl:0113","ngsl:0566","ngsl:0799","ngsl:0323","ngsl:0384"]},
  {"id":"a2e-bug-report","level":"A2","stream":"engineering","title":{"en":"A Simple Bug Report","ru":"Простой баг-репорт"},"blurb":{"en":"A junior engineer files a bug report. Learn the basic structure: steps to reproduce, expected result, actual result.","ru":"Джуниор-инженер оформляет баг-репорт. Изучаем базовую структуру: шаги для воспроизведения, ожидаемый результат, фактический результат."},"source":{"en":"Bug report in an issue tracker","ru":"Баг-репорт в трекере задач"},"passages":[{"en":"Title: Login button does not work on mobile\nReporter: Alex K.\nSeverity: High","ru":"Название: Кнопка входа не работает на мобильном\nАвтор: Алекс К.\nСерьёзность: Высокая","words":[{"id":"a2e-bug-report-w1","w":"severity","ru":"серьёзность (степень важности бага)","gloss":"how serious or dangerous a bug is","pos":"noun","ipa":"/sɪˈvɛrɪti/","example":"This bug has high severity — users cannot log in."},{"id":"a2e-bug-report-w2","w":"reporter","ru":"автор репорта (тот, кто сообщил о баге)","gloss":"the person who found and reported the bug","pos":"noun","ipa":"/rɪˈpɔːtər/","example":"The reporter added a screenshot to the issue."}]},{"en":"Steps to reproduce:\n1. Open the app on a mobile phone.\n2. Go to the login page.\n3. Enter your email and password.\n4. Tap the Login button.","ru":"Шаги для воспроизведения:\n1. Откройте приложение на мобильном телефоне.\n2. Перейдите на страницу входа.\n3. Введите email и пароль.\n4. Нажмите кнопку «Войти».","words":[{"id":"a2e-bug-report-w3","w":"reproduce","ru":"воспроизвести (баг)","gloss":"to make a bug happen again by following the same steps","pos":"verb","ipa":"/ˌriːprəˈdjuːs/","example":"Can you reproduce this error on your machine?"},{"id":"a2e-bug-report-w4","w":"tap","ru":"нажать (на сенсорном экране)","gloss":"to touch the screen once with your finger","pos":"verb","ipa":"/tæp/","example":"Tap the button to confirm."}]},{"en":"Expected result: The user logs in and sees the home screen.","ru":"Ожидаемый результат: Пользователь входит в систему и видит главный экран.","words":[{"id":"a2e-bug-report-w5","w":"expected","ru":"ожидаемый","gloss":"what you think should happen if the app works correctly","pos":"adj","ipa":"/ɪkˈspɛktɪd/","example":"The expected result is a success message."}]},{"en":"Actual result: Nothing happens. The page does not change. There is no error message. The user stays on the login page.","ru":"Фактический результат: Ничего не происходит. Страница не меняется. Сообщения об ошибке нет. Пользователь остаётся на странице входа.","words":[{"id":"a2e-bug-report-w6","w":"actual","ru":"фактический (то, что происходит на самом деле)","gloss":"what really happens, compared to what you expected","pos":"adj","ipa":"/ˈæktʃuəl/","example":"The actual result was very different from expected."}]},{"en":"Additional notes: This bug only happens on iOS Safari. On desktop Chrome, the button works fine. I tested on iPhone 13, iOS 17. I did not see this issue before the last deploy.","ru":"Дополнительные заметки: Этот баг встречается только в Safari на iOS. В Chrome на десктопе кнопка работает нормально. Я проверял на iPhone 13, iOS 17. До последнего деплоя этой проблемы не было.","words":[{"id":"a2e-bug-report-w7","w":"deploy","ru":"деплой (выпуск новой версии на сервер)","gloss":"a release that puts new code on the live server","pos":"noun","ipa":"/dɪˈplɔɪ/","example":"The bug appeared after the last deploy."},{"id":"a2e-bug-report-w8","w":"issue","ru":"проблема, ошибка (также: задача в трекере)","gloss":"a problem or bug; also a task in an issue tracker","pos":"noun","ipa":"/ˈɪʃuː/","example":"Open an issue on GitHub to track this bug."}]}],"phrases":[{"id":"a2e-bug-report-p1","en":"Steps to reproduce","ru":"Шаги для воспроизведения","note":{"en":"A numbered list that shows how to make the bug happen again.","ru":"Пронумерованный список, показывающий, как повторить баг."}},{"id":"a2e-bug-report-p2","en":"Expected result","ru":"Ожидаемый результат","note":{"en":"What should happen if the app works correctly.","ru":"Что должно произойти, если приложение работает правильно."}},{"id":"a2e-bug-report-p3","en":"Actual result","ru":"Фактический результат","note":{"en":"What really happens — usually the broken behavior.","ru":"Что происходит на самом деле — обычно поломанное поведение."}},{"id":"a2e-bug-report-p4","en":"works fine","ru":"работает нормально","note":{"en":"No problem here; use it to narrow down where the bug lives.","ru":"Проблем нет; используется, чтобы сузить область поиска бага."}}],"questions":[{"id":"a2e-bug-report-q1","q":{"en":"On which device and browser does the bug happen?","ru":"На каком устройстве и браузере появляется баг?"},"options":[{"en":"Desktop Chrome","ru":"Chrome на десктопе"},{"en":"iOS Safari on an iPhone","ru":"Safari на iOS, iPhone"},{"en":"Android Firefox","ru":"Firefox на Android"}],"answer":1,"explain":{"en":"Alex writes: 'This bug only happens on iOS Safari.' Desktop Chrome works fine.","ru":"Алекс пишет: «Этот баг встречается только в Safari на iOS». В Chrome на десктопе всё работает."}},{"id":"a2e-bug-report-q2","q":{"en":"What is the expected result when the user taps the Login button?","ru":"Каков ожидаемый результат, когда пользователь нажимает кнопку входа?"},"options":[{"en":"An error message appears.","ru":"Появляется сообщение об ошибке."},{"en":"The user logs in and sees the home screen.","ru":"Пользователь входит и видит главный экран."},{"en":"The page reloads from the beginning.","ru":"Страница перезагружается с начала."}],"answer":1,"explain":{"en":"The bug report says: 'Expected result: The user logs in and sees the home screen.'","ru":"В репорте написано: «Ожидаемый результат: пользователь входит в систему и видит главный экран»."}},{"id":"a2e-bug-report-q3","q":{"en":"What is the actual result after tapping Login?","ru":"Каков фактический результат после нажатия кнопки входа?"},"options":[{"en":"A red error message appears.","ru":"Появляется красное сообщение об ошибке."},{"en":"The app crashes completely.","ru":"Приложение полностью вылетает."},{"en":"Nothing happens; the user stays on the login page.","ru":"Ничего не происходит; пользователь остаётся на странице входа."}],"answer":2,"explain":{"en":"'Nothing happens. The page does not change. The user stays on the login page.'","ru":"«Ничего не происходит. Страница не меняется. Пользователь остаётся на странице входа»."}},{"id":"a2e-bug-report-q4","q":{"en":"When did the bug first appear, according to Alex?","ru":"Когда впервые появился баг, по словам Алекса?"},"options":[{"en":"It has always been there.","ru":"Он был всегда."},{"en":"After the last deploy.","ru":"После последнего деплоя."},{"en":"After updating the iPhone.","ru":"После обновления iPhone."}],"answer":1,"explain":{"en":"Alex says: 'I did not see this issue before the last deploy.'","ru":"Алекс пишет: «До последнего деплоя этой проблемы не было»."}}],"targetWords":["ngsl:0218","ngsl:0477","ngsl:0314","ngsl:0457","ngsl:0580"]},
  {"id":"a2e-ask-for-help","level":"A2","stream":"engineering","title":{"en":"Asking a Teammate for Help","ru":"Просим помощи у коллеги"},"blurb":{"en":"A chat where a junior engineer asks a senior for help with an error. Real phrases you will use every week.","ru":"Переписка, в которой джуниор-инженер просит помощи у сеньора из-за ошибки. Реальные фразы, которые ты будешь использовать каждую неделю."},"source":{"en":"Team chat (Slack / Telegram)","ru":"Командный чат (Slack / Telegram)"},"passages":[{"en":"Mia: Hey Sam, sorry to bother you. Do you have a minute? I'm stuck on something and I don't know how to fix it.","ru":"Миа: Привет, Сэм, извини, что отвлекаю. Есть минутка? Я застряла на одной вещи и не знаю, как это исправить.","words":[{"id":"a2e-ask-for-help-w1","w":"stuck","ru":"застрял(-а), не могу продвинуться","gloss":"unable to continue because of a problem","pos":"adj","ipa":"/stʌk/","example":"I'm stuck on this bug for two hours."},{"id":"a2e-ask-for-help-w2","w":"bother","ru":"беспокоить, отвлекать","gloss":"to disturb someone when they are busy","pos":"verb","ipa":"/ˈbɒðər/","example":"Sorry to bother you — quick question."}]},{"en":"Sam: Of course! What's the problem?\n\nMia: I'm getting an error when I run the tests. It says: 'Cannot read properties of undefined'. I don't understand what that means.","ru":"Сэм: Конечно! В чём проблема?\n\nМиа: Когда я запускаю тесты, появляется ошибка. Написано: 'Cannot read properties of undefined'. Я не понимаю, что это значит.","words":[{"id":"a2e-ask-for-help-w3","w":"error","ru":"ошибка (в коде или программе)","gloss":"a message that tells you something went wrong","pos":"noun","ipa":"/ˈɛrər/","example":"Fix the error before you push."},{"id":"a2e-ask-for-help-w4","w":"undefined","ru":"undefined — переменная без значения","gloss":"a value that has not been set; JavaScript says 'undefined' when a variable has no value","pos":"abbr","ipa":"/ˌʌndɪˈfaɪnd/","example":"If you forget to initialise a variable, it is undefined."}]},{"en":"Sam: Ah, that error means you are trying to use a variable, but it has no value. Can you share the line where the error happens?\n\nMia: Sure! Here it is: user.profile.name. The error is on line 42.","ru":"Сэм: А, эта ошибка означает, что ты пытаешься использовать переменную, у которой нет значения. Можешь показать строку, где возникает ошибка?\n\nМиа: Конечно! Вот она: user.profile.name. Ошибка на строке 42.","words":[{"id":"a2e-ask-for-help-w5","w":"variable","ru":"переменная","gloss":"a named place in your code that stores a value","pos":"noun","ipa":"/ˈvɛəriəbl/","example":"Set the variable before you use it."},{"id":"a2e-ask-for-help-w6","w":"line","ru":"строка (в коде)","gloss":"one row of code in a file, identified by a number","pos":"noun","ipa":"/laɪn/","example":"The error is on line 42."}]},{"en":"Sam: I see the problem. The variable 'user' is null here — it means no user is loaded yet. You need to check if user exists before reading profile. Add an if-check: if (user) { ... }","ru":"Сэм: Вижу проблему. Переменная 'user' здесь null — это значит, что пользователь ещё не загружен. Нужно проверить, существует ли user, прежде чем читать profile. Добавь проверку: if (user) { ... }","words":[{"id":"a2e-ask-for-help-w7","w":"null","ru":"null — намеренно пустое значение","gloss":"an intentional empty value; the variable exists but has nothing in it","pos":"noun","ipa":"/nʌl/","example":"If the user is not found, return null."},{"id":"a2e-ask-for-help-w8","w":"check","ru":"проверить","gloss":"to look at something to make sure it is correct or exists","pos":"verb","ipa":"/tʃɛk/","example":"Always check the value before using it."}]},{"en":"Mia: Oh! That makes sense. I added the check and the tests are green now. Thank you so much, Sam!\n\nSam: Happy to help! Don't hesitate to ask next time.","ru":"Миа: О! Понятно. Я добавила проверку, и тесты теперь зелёные. Большое спасибо, Сэм!\n\nСэм: Всегда пожалуйста! Не стесняйся спрашивать в следующий раз.","words":[{"id":"a2e-ask-for-help-w9","w":"hesitate","ru":"стесняться, колебаться","gloss":"to pause because you are not sure or feel nervous","pos":"verb","ipa":"/ˈhɛzɪteɪt/","example":"Don't hesitate to ask questions."},{"id":"a2e-ask-for-help-w10","w":"green","ru":"зелёные (тесты прошли)","gloss":"in a CI/test context: all tests pass and show green","pos":"adj","ipa":"/ɡriːn/","example":"All tests are green — we can deploy."}]}],"phrases":[{"id":"a2e-ask-for-help-p1","en":"Sorry to bother you — do you have a minute?","ru":"Извини, что отвлекаю — есть минутка?","note":{"en":"A polite way to start a question in chat. Always use before asking for help.","ru":"Вежливое начало вопроса в чате. Используй всегда перед просьбой о помощи."}},{"id":"a2e-ask-for-help-p2","en":"I'm stuck on…","ru":"Я застрял(-а) на…","note":{"en":"Say what you are stuck on. Be specific: 'I'm stuck on the login error.'","ru":"Скажи, на чём застрял(-а). Будь конкретным: «Я застрял(-а) на ошибке входа»."}},{"id":"a2e-ask-for-help-p3","en":"Can you share the line where the error happens?","ru":"Можешь показать строку, где возникает ошибка?","note":{"en":"A useful question when helping someone debug — always ask for the exact location.","ru":"Полезный вопрос при отладке — всегда спрашивай точное место ошибки."}},{"id":"a2e-ask-for-help-p4","en":"Don't hesitate to ask.","ru":"Не стесняйся спрашивать.","note":{"en":"Said by a senior to a junior to show they are welcome to ask more questions.","ru":"Говорит сеньор джуниору, показывая, что тот может задавать вопросы в любое время."}},{"id":"a2e-ask-for-help-p5","en":"tests are green","ru":"тесты зелёные (все прошли)","note":{"en":"All tests pass. 'Red' means at least one test fails.","ru":"Все тесты прошли. «Красные» — значит хотя бы один упал."}}],"questions":[{"id":"a2e-ask-for-help-q1","q":{"en":"Why does Mia contact Sam?","ru":"Почему Миа обращается к Сэму?"},"options":[{"en":"She wants to review Sam's code.","ru":"Она хочет проверить код Сэма."},{"en":"She has an error she cannot fix alone.","ru":"У неё ошибка, которую она не может исправить самостоятельно."},{"en":"She is asking for the day off.","ru":"Она просит выходной."}],"answer":1,"explain":{"en":"Mia says she is stuck and doesn't know how to fix an error she is getting when she runs the tests.","ru":"Миа говорит, что застряла и не знает, как исправить ошибку, которая появляется при запуске тестов."}},{"id":"a2e-ask-for-help-q2","q":{"en":"What does Sam say the error message means?","ru":"Что, по словам Сэма, означает сообщение об ошибке?"},"options":[{"en":"The test file is missing.","ru":"Файл с тестом отсутствует."},{"en":"The code is trying to use a variable that has no value.","ru":"Код пытается использовать переменную, у которой нет значения."},{"en":"There is a typo in the function name.","ru":"В имени функции опечатка."}],"answer":1,"explain":{"en":"Sam explains: 'You are trying to use a variable, but it has no value.'","ru":"Сэм объясняет: «Ты пытаешься использовать переменную, у которой нет значения»."}},{"id":"a2e-ask-for-help-q3","q":{"en":"How does Mia fix the problem?","ru":"Как Миа исправляет проблему?"},"options":[{"en":"She deletes the line with the error.","ru":"Она удаляет строку с ошибкой."},{"en":"She adds an if-check to test that the user exists first.","ru":"Она добавляет проверку if, чтобы сначала убедиться, что пользователь существует."},{"en":"She restarts the server.","ru":"Она перезапускает сервер."}],"answer":1,"explain":{"en":"Sam suggests adding 'if (user) { ... }' and Mia confirms: 'I added the check and the tests are green now.'","ru":"Сэм предлагает добавить 'if (user) { ... }', и Миа подтверждает: «Я добавила проверку, и тесты теперь зелёные»."}},{"id":"a2e-ask-for-help-q4","q":{"en":"What does 'tests are green' mean?","ru":"Что означает «тесты зелёные»?"},"options":[{"en":"The tests need more work.","ru":"Тесты требуют доработки."},{"en":"All tests pass successfully.","ru":"Все тесты успешно проходят."},{"en":"The tests were deleted.","ru":"Тесты были удалены."}],"answer":1,"explain":{"en":"In CI and testing, green means all tests pass. Red means at least one test fails.","ru":"В CI и тестировании зелёный означает, что все тесты прошли. Красный — что хотя бы один упал."}}],"targetWords":["ngsl:0133","ngsl:0134","ngsl:0192","ngsl:0580","ngsl:0050"]},
  {"id":"a2e-readme-intro","level":"A2","stream":"engineering","title":{"en":"Reading a README","ru":"Читаем README"},"blurb":{"en":"The opening of a project README — what the tool does and how to install and run it.","ru":"Начало файла README проекта — что делает инструмент и как его установить и запустить."},"source":{"en":"Project README file","ru":"Файл README проекта"},"passages":[{"en":"# logwatch\n\nlogwatch is a small command-line tool. It reads log files and shows errors in one place.","ru":"# logwatch\n\nlogwatch — это небольшой инструмент командной строки. Он читает лог-файлы и показывает ошибки в одном месте.","words":[{"id":"a2e-readme-intro-w1","w":"command-line tool","ru":"утилита командной строки","gloss":"a program you run by typing text in the terminal, not clicking buttons","pos":"phrase","example":"git is a command-line tool."},{"id":"a2e-readme-intro-w2","w":"log file","ru":"лог-файл","gloss":"a file where a program writes what it did — useful for finding errors","pos":"phrase","example":"Check the log file to find the error."}]},{"en":"## Install\n\nYou need Node.js 18 or higher. Run this command in your terminal:\n\n```\nnpm install -g logwatch\n```","ru":"## Установка\n\nВам нужен Node.js 18 или выше. Выполните эту команду в терминале:\n\n```\nnpm install -g logwatch\n```","words":[{"id":"a2e-readme-intro-w3","w":"install","ru":"установить","gloss":"to put a program on your computer so you can use it","pos":"verb","ipa":"/ɪnˈstɔːl/","example":"Run npm install to install all packages."},{"id":"a2e-readme-intro-w4","w":"terminal","ru":"терминал","gloss":"the text window where you type commands to control your computer","pos":"noun","ipa":"/ˈtɜːmɪnəl/","example":"Open a terminal and type the command."}]},{"en":"## Run\n\nGo to your project folder. Then start logwatch:\n\n```\nlogwatch --dir ./logs\n```\n\nlogwatch will check the folder every 10 seconds.","ru":"## Запуск\n\nПерейдите в папку вашего проекта. Затем запустите logwatch:\n\n```\nlogwatch --dir ./logs\n```\n\nlogwatch будет проверять папку каждые 10 секунд.","words":[{"id":"a2e-readme-intro-w5","w":"run","ru":"запустить / выполнить","gloss":"to start and execute a program or command","pos":"verb","ipa":"/rʌn/","example":"Run the script with: node index.js"},{"id":"a2e-readme-intro-w6","w":"folder","ru":"папка / директория","gloss":"a place on your computer where you store files (also called a directory)","pos":"noun","ipa":"/ˈfəʊldər/","example":"Put all your source files in the src folder."}]},{"en":"## Help\n\nIf something does not work, open an issue on GitHub. Include the error message and your Node.js version.","ru":"## Помощь\n\nЕсли что-то не работает, откройте issue на GitHub. Укажите сообщение об ошибке и версию Node.js.","words":[{"id":"a2e-readme-intro-w7","w":"issue","ru":"задача / проблема (на GitHub)","gloss":"a bug report or question you submit in a project's tracker on GitHub","pos":"noun","ipa":"/ˈɪʃuː/","example":"Open an issue if you find a bug."},{"id":"a2e-readme-intro-w8","w":"error message","ru":"сообщение об ошибке","gloss":"text the program shows when something goes wrong","pos":"phrase","example":"Copy the error message and paste it in the issue."}]}],"phrases":[{"id":"a2e-readme-intro-p1","en":"Run this command","ru":"Выполните эту команду","note":{"en":"READMEs use the imperative form: 'Run', 'Open', 'Install'. It means 'please do this'.","ru":"В README используется форма повелительного наклонения: «Run», «Open», «Install». Это значит «пожалуйста, сделайте это»."}},{"id":"a2e-readme-intro-p2","en":"or higher","ru":"или выше","note":{"en":"'Node.js 18 or higher' means version 18, 19, 20, … — any newer version is also fine.","ru":"«Node.js 18 or higher» означает версию 18, 19, 20 — любая более новая версия тоже подходит."}},{"id":"a2e-readme-intro-p3","en":"include the error message","ru":"укажите сообщение об ошибке","note":{"en":"When reporting a bug, always copy the full error text. It helps maintainers understand what went wrong.","ru":"При сообщении об ошибке всегда копируйте полный текст ошибки. Это помогает разработчикам понять, что пошло не так."}}],"questions":[{"id":"a2e-readme-intro-q1","q":{"en":"What does logwatch do?","ru":"Что делает logwatch?"},"options":[{"en":"It builds Node.js projects.","ru":"Оно собирает Node.js-проекты."},{"en":"It reads log files and shows errors.","ru":"Оно читает лог-файлы и показывает ошибки."},{"en":"It sends log files to GitHub.","ru":"Оно отправляет лог-файлы на GitHub."}],"answer":1,"explain":{"en":"The README says: 'It reads log files and shows errors in one place.'","ru":"В README написано: «Оно читает лог-файлы и показывает ошибки в одном месте»."}},{"id":"a2e-readme-intro-q2","q":{"en":"Which command installs logwatch?","ru":"Какая команда устанавливает logwatch?"},"options":[{"en":"logwatch --dir ./logs","ru":"logwatch --dir ./logs"},{"en":"npm install -g logwatch","ru":"npm install -g logwatch"},{"en":"node logwatch.js","ru":"node logwatch.js"}],"answer":1,"explain":{"en":"The Install section shows: 'npm install -g logwatch'.","ru":"В разделе «Установка» указано: «npm install -g logwatch»."}},{"id":"a2e-readme-intro-q3","q":{"en":"How often does logwatch check the log folder?","ru":"Как часто logwatch проверяет папку с логами?"},"options":[{"en":"Every 1 second","ru":"Каждую секунду"},{"en":"Every 10 seconds","ru":"Каждые 10 секунд"},{"en":"Every 10 minutes","ru":"Каждые 10 минут"}],"answer":1,"explain":{"en":"'logwatch will check the folder every 10 seconds.'","ru":"«logwatch будет проверять папку каждые 10 секунд»."}},{"id":"a2e-readme-intro-q4","q":{"en":"What should you include when you open an issue?","ru":"Что нужно указать при открытии issue?"},"options":[{"en":"Your name and email","ru":"Своё имя и email"},{"en":"The error message and Node.js version","ru":"Сообщение об ошибке и версию Node.js"},{"en":"A link to your project","ru":"Ссылку на ваш проект"}],"answer":1,"explain":{"en":"The README says 'Include the error message and your Node.js version.'","ru":"В README написано «Укажите сообщение об ошибке и версию Node.js»."}}],"targetWords":["ngsl:0192","ngsl:0218","ngsl:0580","ngsl:0136"]},
  {"id":"a2e-pr-description","level":"A2","stream":"engineering","title":{"en":"A Pull Request Description","ru":"Описание pull request"},"blurb":{"en":"A short PR description that explains what changed in the code and why.","ru":"Короткое описание PR, объясняющее что изменилось в коде и почему."},"source":{"en":"GitHub pull request","ru":"Pull request на GitHub"},"passages":[{"en":"Title: Fix slow response on the user profile page\n\nThis PR fixes a performance issue on the user profile page. The page was taking 4–6 seconds to load.","ru":"Заголовок: Исправить медленный ответ на странице профиля пользователя\n\nЭтот PR исправляет проблему с производительностью на странице профиля пользователя. Страница загружалась за 4–6 секунд.","words":[{"id":"a2e-pr-description-w1","w":"PR","ru":"PR (pull request)","gloss":"short for pull request — a request to add your code changes to the main codebase","pos":"abbr","example":"I opened a PR to fix the bug."},{"id":"a2e-pr-description-w2","w":"performance issue","ru":"проблема с производительностью","gloss":"when something works correctly but is too slow","pos":"phrase","example":"We found a performance issue: the query took 5 seconds."}]},{"en":"## What changed\n\n- Added a database index on the `user_id` column.\n- Removed an extra API call that was not needed.\n- Updated the cache to store results for 5 minutes.","ru":"## Что изменилось\n\n- Добавлен индекс базы данных на столбец `user_id`.\n- Убран лишний вызов API, который не был нужен.\n- Обновлён кэш для хранения результатов на 5 минут.","words":[{"id":"a2e-pr-description-w3","w":"index","ru":"индекс (базы данных)","gloss":"a database structure that makes lookups faster — like a book index","pos":"noun","ipa":"/ˈɪndeks/","example":"Add an index on email to speed up search queries."},{"id":"a2e-pr-description-w4","w":"cache","ru":"кэш","gloss":"a place to store results so the program does not have to recalculate them every time","pos":"noun","ipa":"/kæʃ/","example":"The cache saves the result for 5 minutes."},{"id":"a2e-pr-description-w5","w":"add","ru":"добавить","gloss":"to put something new into the code or system","pos":"verb","ipa":"/æd/","example":"Add a new function to handle errors."}]},{"en":"## Why\n\nUsers reported that the profile page was very slow. After these changes, the page loads in under 300 ms.","ru":"## Почему\n\nПользователи сообщали, что страница профиля очень медленная. После этих изменений страница загружается менее чем за 300 мс.","words":[{"id":"a2e-pr-description-w6","w":"reported","ru":"сообщали","gloss":"told someone about a problem they found","pos":"verb","example":"Users reported the page was slow."}]},{"en":"## Testing\n\nI tested this on the staging server. All existing tests pass. Please review and merge if everything looks good.","ru":"## Тестирование\n\nЯ протестировал это на тестовом сервере. Все существующие тесты проходят. Пожалуйста, проверьте и объедините, если всё выглядит хорошо.","words":[{"id":"a2e-pr-description-w7","w":"staging server","ru":"тестовый сервер (staging)","gloss":"a test copy of the production system — used to check changes before they go live","pos":"phrase","example":"Deploy to the staging server first to test the change."},{"id":"a2e-pr-description-w8","w":"merge","ru":"вмёржить / объединить","gloss":"to accept a PR and combine the new code with the main branch","pos":"verb","ipa":"/mɜːdʒ/","example":"Click 'Merge' to add the changes to main."}]}],"phrases":[{"id":"a2e-pr-description-p1","en":"All existing tests pass.","ru":"Все существующие тесты проходят.","note":{"en":"This is important in every PR — it means the change did not break anything that worked before.","ru":"Это важно в каждом PR — это означает, что изменение не сломало ничего, что работало раньше."}},{"id":"a2e-pr-description-p2","en":"Please review and merge if everything looks good.","ru":"Пожалуйста, проверьте и объедините, если всё выглядит хорошо.","note":{"en":"A polite way to ask a teammate to approve and accept your PR.","ru":"Вежливый способ попросить коллегу одобрить и принять ваш PR."}},{"id":"a2e-pr-description-p3","en":"loads in under 300 ms","ru":"загружается менее чем за 300 мс","note":{"en":"'ms' means milliseconds — 1000 ms = 1 second. 300 ms is very fast for a web page.","ru":"«ms» означает миллисекунды — 1000 мс = 1 секунда. 300 мс — очень быстро для веб-страницы."}}],"questions":[{"id":"a2e-pr-description-q1","q":{"en":"What problem does this PR fix?","ru":"Какую проблему исправляет этот PR?"},"options":[{"en":"A broken login form","ru":"Сломанная форма входа"},{"en":"A slow user profile page","ru":"Медленная страница профиля пользователя"},{"en":"A missing database table","ru":"Отсутствующая таблица в базе данных"}],"answer":1,"explain":{"en":"The title says 'Fix slow response on the user profile page'.","ru":"В заголовке написано «Исправить медленный ответ на странице профиля пользователя»."}},{"id":"a2e-pr-description-q2","q":{"en":"How long did the page take to load before the fix?","ru":"Сколько времени страница загружалась до исправления?"},"options":[{"en":"Under 300 ms","ru":"Менее 300 мс"},{"en":"About 1 second","ru":"Около 1 секунды"},{"en":"4–6 seconds","ru":"4–6 секунд"}],"answer":2,"explain":{"en":"The PR says 'The page was taking 4–6 seconds to load.'","ru":"В PR написано «Страница загружалась за 4–6 секунд»."}},{"id":"a2e-pr-description-q3","q":{"en":"Where did the developer test the changes?","ru":"Где разработчик протестировал изменения?"},"options":[{"en":"On the production server","ru":"На рабочем сервере"},{"en":"On the staging server","ru":"На тестовом сервере"},{"en":"On a local machine only","ru":"Только на локальной машине"}],"answer":1,"explain":{"en":"'I tested this on the staging server.'","ru":"«Я протестировал это на тестовом сервере»."}},{"id":"a2e-pr-description-q4","q":{"en":"Which of these was NOT a change in this PR?","ru":"Что из перечисленного НЕ является изменением в этом PR?"},"options":[{"en":"Added a database index","ru":"Добавлен индекс базы данных"},{"en":"Removed an extra API call","ru":"Убран лишний вызов API"},{"en":"Rewrote the login page","ru":"Переписана страница входа"}],"answer":2,"explain":{"en":"The PR lists three changes: index, API call removal, and cache update. The login page is not mentioned.","ru":"В PR перечислены три изменения: индекс, удаление вызова API и обновление кэша. Страница входа не упоминается."}}],"targetWords":["ngsl:0414","ngsl:0192","ngsl:0580"]},
  {"id":"a2e-oncall-ping","level":"A2","stream":"engineering","title":{"en":"An On-Call Alert","ru":"Дежурное оповещение"},"blurb":{"en":"A message in Slack saying a service is down — and the first steps to respond.","ru":"Сообщение в Slack о том, что сервис не работает, и первые шаги для ответа."},"source":{"en":"Team Slack channel","ru":"Командный канал в Slack"},"passages":[{"en":"@here 🚨 ALERT: The payment service is down. Users cannot complete orders. This started at 14:32 UTC.","ru":"@here 🚨 ОПОВЕЩЕНИЕ: Платёжный сервис не работает. Пользователи не могут завершить заказы. Это началось в 14:32 UTC.","words":[{"id":"a2e-oncall-ping-w1","w":"service","ru":"сервис","gloss":"a program or system that runs on a server and does one specific job","pos":"noun","ipa":"/ˈsɜːvɪs/","example":"The payment service handles all card transactions."},{"id":"a2e-oncall-ping-w2","w":"down","ru":"не работает / упал","gloss":"not working; a service is 'down' when users cannot use it","pos":"adv","ipa":"/daʊn/","example":"The API is down — all requests are failing."},{"id":"a2e-oncall-ping-w3","w":"UTC","ru":"UTC (всемирное координированное время)","gloss":"the standard time used in tech logs and alerts — everyone uses it to avoid timezone confusion","pos":"abbr","example":"The incident started at 09:00 UTC."}]},{"en":"Error rate is 100%. The last deployment was 20 minutes ago (v2.4.1). Logs show a database connection error.","ru":"Частота ошибок — 100%. Последнее развёртывание было 20 минут назад (v2.4.1). Логи показывают ошибку соединения с базой данных.","words":[{"id":"a2e-oncall-ping-w4","w":"error rate","ru":"частота ошибок","gloss":"what percentage of requests are failing — 100% means every request fails","pos":"phrase","example":"The error rate went from 0% to 100% after the deploy."},{"id":"a2e-oncall-ping-w5","w":"deployment","ru":"развёртывание (деплой)","gloss":"putting new code onto the production server so users get it","pos":"noun","ipa":"/dɪˈplɔɪmənt/","example":"The last deployment was 20 minutes ago."},{"id":"a2e-oncall-ping-w6","w":"connection error","ru":"ошибка соединения","gloss":"the program tried to connect to another system (like a database) but failed","pos":"phrase","example":"Logs show a database connection error."}]},{"en":"First steps:\n1. Check the database status in the dashboard.\n2. If the database is OK, roll back the deployment.\n3. Send a status update here in 10 minutes.","ru":"Первые шаги:\n1. Проверьте статус базы данных в панели управления.\n2. Если база данных в порядке, откатите развёртывание.\n3. Отправьте обновление статуса сюда через 10 минут.","words":[{"id":"a2e-oncall-ping-w7","w":"roll back","ru":"откатить","gloss":"to return to the previous version of the code because the new one has a problem","pos":"phrase","example":"Roll back the deployment to v2.4.0."},{"id":"a2e-oncall-ping-w8","w":"dashboard","ru":"панель управления / дашборд","gloss":"a web page that shows the current health and metrics of your services","pos":"noun","ipa":"/ˈdæʃbɔːrd/","example":"Open the dashboard to see if the database is running."}]},{"en":"Who is on call now? Please respond here. Stop all other deploys until this is fixed.","ru":"Кто сейчас дежурит? Пожалуйста, ответьте здесь. Остановите все другие развёртывания до устранения проблемы.","words":[{"id":"a2e-oncall-ping-w9","w":"on call","ru":"на дежурстве","gloss":"available to respond to urgent problems, even outside normal work hours","pos":"phrase","example":"I am on call this weekend."},{"id":"a2e-oncall-ping-w10","w":"stop","ru":"остановить / прекратить","gloss":"to not do something until the problem is resolved","pos":"verb","ipa":"/stɒp/","example":"Stop all deploys until the issue is fixed."}]}],"phrases":[{"id":"a2e-oncall-ping-p1","en":"is down","ru":"не работает / упал","note":{"en":"'The service is down' means the service stopped working and users are affected. 'Down' is the opposite of 'up'.","ru":"«The service is down» означает, что сервис перестал работать и пользователи пострадали. «Down» — противоположность «up»."}},{"id":"a2e-oncall-ping-p2","en":"roll back the deployment","ru":"откатить развёртывание","note":{"en":"When a new deploy causes a problem, rolling back means going back to the last working version. It is the fastest fix.","ru":"Когда новый деплой вызывает проблему, откат означает возврат к последней рабочей версии. Это самый быстрый способ исправить."}},{"id":"a2e-oncall-ping-p3","en":"send a status update","ru":"отправить обновление статуса","note":{"en":"During an incident, the team needs regular short messages: what you know, what you are doing, what is next.","ru":"Во время инцидента команде нужны регулярные короткие сообщения: что вы знаете, что делаете, что будет дальше."}}],"questions":[{"id":"a2e-oncall-ping-q1","q":{"en":"Which service is down?","ru":"Какой сервис не работает?"},"options":[{"en":"The user login service","ru":"Сервис входа пользователей"},{"en":"The payment service","ru":"Платёжный сервис"},{"en":"The notification service","ru":"Сервис уведомлений"}],"answer":1,"explain":{"en":"The alert says 'The payment service is down.'","ru":"В оповещении написано «Платёжный сервис не работает»."}},{"id":"a2e-oncall-ping-q2","q":{"en":"What does the log show as the cause?","ru":"Что показывают логи как причину?"},"options":[{"en":"A missing config file","ru":"Отсутствующий файл конфигурации"},{"en":"A database connection error","ru":"Ошибка соединения с базой данных"},{"en":"A memory limit error","ru":"Ошибка превышения памяти"}],"answer":1,"explain":{"en":"'Logs show a database connection error.'","ru":"«Логи показывают ошибку соединения с базой данных»."}},{"id":"a2e-oncall-ping-q3","q":{"en":"What is the first step in the response plan?","ru":"Каков первый шаг в плане реагирования?"},"options":[{"en":"Roll back the deployment","ru":"Откатить развёртывание"},{"en":"Check the database status in the dashboard","ru":"Проверить статус базы данных в панели управления"},{"en":"Send a status update","ru":"Отправить обновление статуса"}],"answer":1,"explain":{"en":"Step 1 is 'Check the database status in the dashboard.'","ru":"Шаг 1: «Проверьте статус базы данных в панели управления»."}},{"id":"a2e-oncall-ping-q4","q":{"en":"When should the team send a status update?","ru":"Когда команда должна отправить обновление статуса?"},"options":[{"en":"In 5 minutes","ru":"Через 5 минут"},{"en":"In 10 minutes","ru":"Через 10 минут"},{"en":"After the problem is fully fixed","ru":"После полного устранения проблемы"}],"answer":1,"explain":{"en":"'Send a status update here in 10 minutes.'","ru":"«Отправьте обновление статуса сюда через 10 минут»."}}],"targetWords":["ngsl:0223","ngsl:0109","ngsl:0477","ngsl:0323","ngsl:0347"]},
];
